'v+r*c-c':lambda h,w,r,c,v:v+r*c-c,'v+r*c+c':lambda h,w,r,c,v:v+r*c+c,
'v+r*r+c':lambda h,w,r,c,v:v+r*r+c,'v+r+c*c':lambda h,w,r,c,v:v+r+c*c,
}
for name,f in features.items():
 for a in range(3):
  for b in range(3):
