# Explore polynomial modular feature linear models from simple terms
funcs={
'1':lambda h,w,r,c,v:1,'r':lambda h,w,r,c,v:r,'c':lambda h,w,r,c,v:c,'v':lambda h,w,r,c,v:v,
'h':lambda h,w,r,c,v:h,'w':lambda h,w,r,c,v:w,'rc':lambda h,w,r,c,v:r*c,
'rv':lambda h,w,r,c,v:r*v,'cv':lambda h,w,r,c,v:c*v,'r2':lambda h,w,r,c,v:r*r,'c2':lambda h,w,r,c,v:c*c,'v2':lambda h,w,r,c,v:v*v,
'edge':lambda h,w,r,c,v:min(r,c,h-1-r,w-1-c),
'center_r':lambda h,w,r,c,v:abs(2*r-(h-1)),'center_c':lambda h,w,r,c,v:abs(2*c-(w-1)),
}
# combinations of up to 3 features linear mod 3
names=list(funcs)
found=[]
for k in [2,3]:
 for ns in itertools.combinations(names,k):
  if '1' not in ns:continue
  for co in itertools.product(range(3),repeat=k):
   if all(sum(a*funcs[n](h,w,r,c,v) for n,a in zip(ns,co))%3==mp[o] for h,w,r,c,v,o in obs):found.append((ns,co))
 print(k,len(found))
print(found[:10])
